function Verify(n, h, u, v):
    hm <- function(p,q) -> h(n-p, q)
    mirror_ok <- ( EPoly(n,hm,u,v) == (-1)^n * u^n * EPoly(n,h,1/u,v) )
    serre_dual <- forall p,q in 0..n: h(p,q) == h(n-p,n-q)
    serre_ok <- if serre_dual then ( EPoly(n,h,u,v) == (u*v)^n * EPoly(n,h,1/u,1/v) ) else NONE
    return { mirror_equation: mirror_ok, serre_dual: serre_dual, serre_equation: serre_ok }

